Post Date: 2017-03-12T13:05:47Z
Current Date: April 4 2025
Title: Unable to parameterize keyof (in function) to access object's fields
Description: I'm having problems understanding how to parameterize **keyof**. I have extracted a simple code that describes the issue I'm facing.

```ts
interface INested3 {
    id: number;
    name: string;
}

interface INested2a {
    id: number;
    name: string;
    nested3: INested3;
}

interface INested2b {
    id: number;
    name: string;
    nested3: INested3;
}

interface INested1 {
    id: number;
    name: string;
    nested2a: INested2a;
    nested2b: INested2b;
}

interface IFoo {
    id: number;
    name: string;
    nested1: INested1;
}

function get<T, K1 extends keyof T, K2 extends keyof T[K1], K3 extends keyof T[K1][K2]>(obj: T, key1: K1, key2: K2, key3: K3): T[K1][K2][K3] {
    return obj[key1][key2][key3];
}

// Fine
function foo1a(f: IFoo): void {
    console.log(
        get(f, "nested1", "nested2a", "nested3")
    );
}

function foo1b(f: IFoo): void {
    console.log(
        get(f, "nested1", "nested2b", "nested3")
    );
}

// Not fine - why?
// Argument of type '"nested3"' is not assignable to parameter of type '"toString" | "valueOf"'.
function foo1param(f: IFoo, nested2key: keyof INested1): void {
    console.log(
        get(f, "nested1", nested2key, "nested3")
    )
}

var f: IFoo = {
    id: 1,
    name: "Foo",
    nested1: {
        id: 1,
        name: "Nested 1",
        nested2a: {
            id: 1,
            name: "Nested 2A",
            nested3: {
                id: 1,
                name: "Nested 3",
            }
        },
        nested2b: {
            id: 1,
            name: "Nested 2B",
            nested3: {
                id: 2,
                name: "Nested 3",
            }
        }
    }
}

// Would like to use it like this
foo1param(f, "nested2a");
foo1param(f, "nested2b");
```


